# owner: platform
"""Contact sheet for substitute teachers."""

from typing import List, Tuple

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _check(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students to list")
    for item in students:
        if not item.email:
            raise ProjectError(f"no email for {item.display_name}")


def _line(cells: Tuple[str, ...], widths: List[int]) -> str:
    padded = [cell.ljust(width) for cell, width in zip(cells, widths)]
    return "  ".join(padded).rstrip()


# ---
def contact_rows(students: List[Student]) -> List[str]:
    """Rows of name, section and email in columns, sorted by name."""
    _check(students)
    ordered = sorted(students, key=lambda item: item.display_name)
    cells = [(item.display_name, item.section, item.email) for item in ordered]
    widths = [max(len(row[slot]) for row in cells) for slot in range(3)]
    return [_line(row, widths) for row in cells]

