# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows


def _student(last, first, section, email):
    return Student("id", last, first, section, email)


class ContactRowTests(unittest.TestCase):
    # ---
    def test_rows_are_sorted_and_aligned(self):
        rows = contact_rows([
            _student("Young", "Zed", "B", "z@example.invalid"),
            _student("Adams", "Al", "A", "al@example.invalid")
        ])
        self.assertEqual(rows, [
            "Adams, Al   A  al@example.invalid",
            "Young, Zed  B  z@example.invalid"
        ])

    # ---
    def test_missing_email_names_the_student(self):
        with self.assertRaisesRegex(ProjectError, "Adams, Al"):
            contact_rows([_student("Adams", "Al", "A", None)])

    # ---
    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
